PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS school_tenants (id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, country_code TEXT NOT NULL, default_locale TEXT NOT NULL DEFAULT 'en', status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('pending','active','suspended')), public_profile INTEGER NOT NULL DEFAULT 1 CHECK(public_profile IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS school_memberships (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES school_tenants(id), actor_brasa_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('school_admin','teacher','curriculum_reviewer','student','guardian')), status TEXT NOT NULL CHECK(status IN ('invited','active','suspended','revoked')), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, actor_brasa_id, role));
CREATE INDEX IF NOT EXISTS idx_school_memberships_actor ON school_memberships(actor_brasa_id, status);
CREATE TABLE IF NOT EXISTS school_lessons (id TEXT PRIMARY KEY, school_id TEXT NOT NULL REFERENCES school_tenants(id), slug TEXT NOT NULL, locale TEXT NOT NULL DEFAULT 'en', title TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', body_json TEXT NOT NULL, accessibility_json TEXT NOT NULL DEFAULT '{}', offline_eligible INTEGER NOT NULL DEFAULT 1 CHECK(offline_eligible IN (0,1)), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','review','published','archived')), created_by TEXT NOT NULL, updated_by TEXT NOT NULL, published_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(school_id, slug, locale));
CREATE INDEX IF NOT EXISTS idx_school_lessons_public ON school_lessons(school_id, status, locale, updated_at);
CREATE TABLE IF NOT EXISTS school_audit_log (id TEXT PRIMARY KEY, school_id TEXT NOT NULL, actor_brasa_id TEXT NOT NULL, action TEXT NOT NULL, resource_type TEXT NOT NULL, resource_id TEXT NOT NULL, snapshot_json TEXT NOT NULL, occurred_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_school_audit_school ON school_audit_log(school_id, occurred_at);
